function GovernmentServiceAdminPanel() {
  const [records, setRecords] = useState<GovernmentServiceDirectoryEntry[]>([])
  const [filter, setFilter] = useState<'ALL' | 'APPROVED' | 'NEEDS_REVIEW' | 'DISABLED'>('ALL')
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState('')
  const load = useCallback(async () => { setLoading(true); setError(''); try { const response = await api.listGovernmentServicesForAdmin(filter === 'ALL' ? undefined : filter); setRecords(response.services) } catch (err) { setError((err as Error).message) } finally { setLoading(false) } }, [filter])
  useEffect(() => { void load() }, [load])
  const changePublication = async (item: GovernmentServiceDirectoryEntry, publicationStatus: 'APPROVED' | 'NEEDS_REVIEW' | 'DISABLED') => {
    const reason = window.prompt(publicationStatus === 'NEEDS_REVIEW' ? 'سبب إرسال السجل إلى المراجعة:' : publicationStatus === 'DISABLED' ? 'سبب إيقاف النشر:' : 'ملاحظة الاعتماد أو إعادة النشر (اختياري):')
    if (reason === null) return
    try { await api.setGovernmentServicePublication(item.id, publicationStatus, reason || undefined); await load() } catch (err) { setError((err as Error).message) }
  }
  return <section className="government-service-admin"><header className="panel-heading"><div><span className="section-kicker">السجل الوطني للخدمات</span><h2>حوكمة المصادر وحالات النشر</h2><p>كل سجل ظاهر للمواطن لديه مصدر رسمي محفوظ. السجلات قيد المراجعة أو المتوقفة لا تظهر في الدليل العام.</p></div><button className="button outline" onClick={() => void load()} disabled={loading}><RefreshCw className={loading ? 'spin' : ''} /> تحديث</button></header><nav className="service-admin-filters">{([['ALL', 'كل السجلات'], ['APPROVED', 'منشور'], ['NEEDS_REVIEW', 'قيد المراجعة'], ['DISABLED', 'متوقف']] as const).map(([value, label]) => <button type="button" className={filter === value ? 'active' : ''} onClick={() => setFilter(value)} key={value}>{label}</button>)}</nav>{error && <div className="form-error"><AlertTriangle /> {error}</div>}{loading ? <div className="loading-state"><RefreshCw className="spin" /> جاري تحميل السجل...</div> : <div className="service-admin-list">{records.map(item => <article key={item.id}><div><span className={`service-publication ${item.publicationStatus.toLowerCase()}`}>{item.publicationStatus === 'APPROVED' ? 'منشور' : item.publicationStatus === 'NEEDS_REVIEW' ? 'قيد المراجعة' : item.publicationStatus === 'DISABLED' ? 'متوقف' : 'مسودة'}</span><h3>{item.shortNameAr || item.officialNameAr}</h3><p>{item.responsibleMinistry || item.responsibleAuthority || 'الجهة المختصة'} • آخر تحقق: {item.lastVerifiedDate || 'غير محدد'}</p><a href={item.sources[0]?.officialUrl} target="_blank" rel="noreferrer">فتح المصدر الرسمي <ExternalLink /></a></div><div className="service-admin-actions">{item.publicationStatus !== 'NEEDS_REVIEW' && <button className="button outline" onClick={() => void changePublication(item, 'NEEDS_REVIEW')}>إرسال للمراجعة</button>}{item.publicationStatus !== 'DISABLED' && <button className="button ghost" onClick={() => void changePublication(item, 'DISABLED')}>إيقاف النشر</button>}{item.publicationStatus !== 'APPROVED' && <button className="button primary" onClick={() => void changePublication(item, 'APPROVED')}>نشر بعد التحقق</button>}</div></article>)}</div>}</section>
}

function NewRequestAlertsPanel({ scope }: { scope: 'admin' | 'operations' }) {
  const [alerts, setAlerts] = useState<Array<{ reference: string; serviceName: string; department: string; status: string; createdAt: string; updatedAt: string }>>([])
  const [soundEnabled, setSoundEnabled] = useState(false)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState('')
  const knownReferences = useRef(new Set<string>())
  const playNotificationTone = () => {
    try { const AudioContextClass = window.AudioContext || (window as typeof window & { webkitAudioContext?: typeof AudioContext }).webkitAudioContext; if (!AudioContextClass) return; const context = new AudioContextClass(); const oscillator = context.createOscillator(); const gain = context.createGain(); oscillator.type = 'sine'; oscillator.frequency.setValueAtTime(880, context.currentTime); gain.gain.setValueAtTime(0.0001, context.currentTime); gain.gain.exponentialRampToValueAtTime(0.08, context.currentTime + 0.025); gain.gain.exponentialRampToValueAtTime(0.0001, context.currentTime + 0.28); oscillator.connect(gain).connect(context.destination); oscillator.start(); oscillator.stop(context.currentTime + 0.3); setTimeout(() => void context.close(), 500) } catch { /* Browser may block sound until interaction; the visual alert remains available. */ }
  }
  const load = useCallback(async (allowSound = false) => { try { const response = await api.getNewRequestAlerts(); const next = response.alerts; const hasNew = next.some(item => knownReferences.current.size > 0 && !knownReferences.current.has(item.reference)); knownReferences.current = new Set(next.map(item => item.reference)); setAlerts(next); if (allowSound && soundEnabled && hasNew) playNotificationTone(); setError('') } catch (item) { setError((item as Error).message) } finally { setLoading(false) } }, [soundEnabled])
  useEffect(() => { void load(false); const timer = window.setInterval(() => void load(true), 20_000); return () => window.clearInterval(timer) }, [load])
  const enableSound = () => { const next = !soundEnabled; setSoundEnabled(next); if (next) playNotificationTone() }
  return <section className={`new-request-alerts ${scope}`} id={scope === 'operations' ? 'operations-alerts' : 'admin-alerts'}><header className="panel-heading"><div><span className="section-kicker">متابعة فورية</span><h2>طلبات جديدة</h2><p>تُحدّث كل 20 ثانية من الطلبات المسجلة في المنصة. يظهر صوت التنبيه بعد تفعيله من هذا الزر.</p></div><div className="alerts-actions"><button type="button" className={soundEnabled ? 'button primary' : 'button outline'} onClick={enableSound}><Bell /> {soundEnabled ? 'الصوت مفعّل' : 'تفعيل صوت التنبيه'}</button><button type="button" className="button ghost" onClick={() => void load(false)} disabled={loading}><RefreshCw className={loading ? 'spin' : ''} /> تحديث</button></div></header>{error && <div className="form-error"><AlertTriangle /> {error}</div>}{alerts.length === 0 && !loading ? <div className="admin-empty-state"><Bell /><span>لا توجد طلبات جديدة بانتظار المراجعة حالياً.</span></div> : <div className="new-request-alert-list">{alerts.map(item => <article key={item.reference}><span className="new-request-dot" /><div><strong>{item.serviceName}</strong><small>{item.reference} • {item.department}</small></div><time>{new Date(item.createdAt).toLocaleString('en-GB')}</time>{scope === 'admin' && <Link className="button outline" href="/employee#employee-service-requests">فتح المعاملة <ArrowLeft /></Link>}</article>)}</div>}</section>
}

function DepartmentManagementPanel() {
  const [departments, setDepartments] = useState<DepartmentWorkbench[]>([])
  const [selectedId, setSelectedId] = useState('')
  const [loading, setLoading] = useState(true)
  const [busyService, setBusyService] = useState<string | null>(null)
  const [error, setError] = useState('')
  const load = useCallback(async () => { setLoading(true); setError(''); try { const result = await api.getDepartmentWorkbench(); setDepartments(result.departments); setSelectedId(current => current || result.departments[0]?.id || '') } catch (item) { setError((item as Error).message) } finally { setLoading(false) } }, [])
  useEffect(() => { void load() }, [load])
  const selected = departments.find(item => item.id === selectedId) || departments[0]
  const updateRequirements = async (service: DepartmentWorkbench['services'][number]) => {
    const entered = window.prompt('اكتب المتطلبات، كل متطلب في سطر مستقل:', service.requiredDocuments.join('\n'))
    if (entered === null) return
    const requiredDocuments = entered.split('\n').map(item => item.trim()).filter(Boolean)
    if (!requiredDocuments.length) return setError('أدخل متطلباً واحداً على الأقل أو ألغِ العملية.')
    setBusyService(service.id); setError('')
    try { await api.updatePlatformService(service.id, { requiredDocuments }); await load() } catch (item) { setError((item as Error).message) } finally { setBusyService(null) }
  }
  const toggleService = async (service: DepartmentWorkbench['services'][number]) => {
    setBusyService(service.id); setError('')
    try { await api.updatePlatformService(service.id, { active: !service.active }); await load() } catch (item) { setError((item as Error).message) } finally { setBusyService(null) }
  }
  return <section className="department-management-panel"><header className="panel-heading"><div><span className="section-kicker">إدارة حسب الدائرة</span><h2>الطلبات والخدمات والمتطلبات</h2><p>اختر دائرة لمتابعة الطلبات الواردة وخدماتها ومتطلبات كل خدمة. تظهر البيانات المسجلة في المنصة فقط.</p></div><button className="button outline" onClick={() => void load()} disabled={loading}><RefreshCw className={loading ? 'spin' : ''} /> تحديث</button></header>{error && <div className="form-error"><AlertTriangle /> {error}</div>}{loading ? <div className="loading-state"><RefreshCw className="spin" /> جاري تحميل الدوائر...</div> : <><div className="department-workbench-tabs">{departments.map(item => <button type="button" key={item.id} className={selected?.id === item.id ? 'active' : ''} onClick={() => setSelectedId(item.id)}>{item.name}<small>{item.requests.length.toLocaleString('en-US')} طلب</small></button>)}</div>{selected && <div className="department-workbench-content"><header><div><span>{selected.category} • {selected.district}</span><h3>{selected.name}</h3><p>{selected.dataStatus === 'VERIFIED_SOURCE' ? 'الجهة ضمن سجل مصدر موثق.' : 'بيانات الجهة تحتاج تحققاً إضافياً قبل استخدامها كمصدر رسمي.'}</p></div>{selected.sourceUrl && <a className="button outline" href={selected.sourceUrl} target="_blank" rel="noreferrer">مصدر الدائرة <ExternalLink /></a>}</header><div className="department-workbench-grid"><section><h4><FileText /> طلبات المواطنين</h4>{selected.requests.length === 0 ? <div className="admin-empty-state"><FileText /><span>لا توجد طلبات مسجلة لهذه الدائرة حالياً.</span></div> : <div className="department-request-list">{selected.requests.map(request => <article key={request.reference}><span className={`status ${request.status.toLowerCase()}`}>{statusLabels[request.status as keyof typeof statusLabels] || request.status}</span><div><strong>{request.serviceName}</strong><small>{request.reference} • {request.citizenName}</small><p>{request.currentAction}</p></div><time>{new Date(request.updatedAt).toLocaleString('en-GB')}</time></article>)}</div>}</section><section><h4><BriefcaseBusiness /> خدمات الدائرة ومتطلباتها</h4>{selected.services.length === 0 ? <div className="admin-empty-state"><BriefcaseBusiness /><span>لم يُسجل لهذه الدائرة نموذج خدمة داخل المنصة بعد.</span></div> : <div className="department-service-list">{selected.services.map(service => <article key={service.id}><header><div><strong>{service.name}</strong><small>{service.category}</small></div><span className={service.active ? 'service-state active' : 'service-state paused'}>{service.active ? 'متاحة' : 'موقوفة'}</span></header><ul>{service.requiredDocuments.map(item => <li key={item}><CheckCircle2 /> {item}</li>)}</ul><footer><button type="button" className="button outline" onClick={() => void updateRequirements(service)} disabled={busyService === service.id}>تعديل المتطلبات</button><button type="button" className="button ghost" onClick={() => void toggleService(service)} disabled={busyService === service.id}>{service.active ? 'إيقاف الاستقبال' : 'إعادة الاستقبال'}</button></footer></article>)}</div>}</section></div></div>}</>}</section>
}

